use std::{env,io::{Read,Write},os::unix::net::UnixStream,time::Duration};
fn send(s:&mut UnixStream,op:u8,b:&[u8]) {let mut h=vec![0x80|op]; match b.len(){0..=125=>h.push(0x80|b.len() as u8),126..=65535=>{h.push(0xfe);h.extend_from_slice(&(b.len() as u16).to_be_bytes())},_=>{h.push(0xff);h.extend_from_slice(&(b.len() as u64).to_be_bytes())}} let mut mask=[0;4];std::fs::File::open("/dev/urandom").unwrap().read_exact(&mut mask).unwrap();h.extend_from_slice(&mask);h.extend(b.iter().enumerate().map(|(i,x)|x^mask[i%4]));s.write_all(&h).unwrap();}
fn receive(s:&mut UnixStream)->String {let mut all=Vec::new();loop{let mut h=[0;2];s.read_exact(&mut h).unwrap();let mut n=(h[1]&127) as u64;if n==126{let mut x=[0;2];s.read_exact(&mut x).unwrap();n=u16::from_be_bytes(x) as u64;}else if n==127{let mut x=[0;8];s.read_exact(&mut x).unwrap();n=u64::from_be_bytes(x);}assert!(n<64*1024*1024);let mut mask=[0;4];if h[1]&128!=0{s.read_exact(&mut mask).unwrap();}let mut b=vec![0;n as usize];s.read_exact(&mut b).unwrap();if h[1]&128!=0{for(i,x)in b.iter_mut().enumerate(){*x^=mask[i%4]}}match h[0]&15{9=>{send(s,10,&b);continue},8=>panic!("server closed"),0|1=>all.extend(b),_=>continue}if h[0]&128!=0{return String::from_utf8(all).unwrap()}}}
fn response(s:&mut UnixStream,id:u8)->String {loop{let x=receive(s);if x.contains(&format!("\"id\":{id},"))||x.contains(&format!("\"id\":{id}}}")){return x}}}
fn main(){let a:Vec<String>=env::args().collect();let mut s=UnixStream::connect("/home/jim/.codex/app-server-control/app-server-control.sock").unwrap();s.set_read_timeout(Some(Duration::from_secs(30))).unwrap();s.write_all(b"GET / HTTP/1.1\r\nHost: localhost\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\nSec-WebSocket-Version: 13\r\n\r\n").unwrap();let mut h=Vec::new();while !h.ends_with(b"\r\n\r\n"){let mut x=[0];s.read_exact(&mut x).unwrap();h.push(x[0]);assert!(h.len()<16384)}assert!(String::from_utf8_lossy(&h).contains("101"),"{}",String::from_utf8_lossy(&h));send(&mut s,1,br#"{"id":1,"method":"initialize","params":{"clientInfo":{"name":"sm_recovery","version":"1"},"capabilities":{"experimentalApi":true}}}"#);let init=response(&mut s,1);assert!(!init.contains("\"error\""),"{init}");send(&mut s,1,br#"{"method":"initialized"}"#);let req=format!("{{\"id\":2,\"method\":\"{}\",\"params\":{}}}",a[1],a[2]);send(&mut s,1,req.as_bytes());println!("{}",response(&mut s,2));send(&mut s,8,&[]);}
